// Immersion index — record JAH-GPC-VRHEADSET-000001
// Property of Justin Addam Higgins (JAH). Deterministic: same inputs, same output.
var m = {"res_mp": 4.2, "refresh_hz": 120, "fov_deg": 100};
var value = (m.res_mp*m.refresh_hz*m.fov_deg/10000);
if (!isFinite(value)) { console.log('DEMO_FAIL|JAH-GPC-VRHEADSET-000001|non-finite'); process.exit(1); }
console.log('DEMO_OK|JAH-GPC-VRHEADSET-000001|' + value.toFixed(2) + ' immersion index');

